import pandas as pd, numpy as np
from pymatgen.core import Structure, Composition
from pymatgen.analysis.structure_matcher import StructureMatcher
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
D=pd.read_csv('cdft_piezo_d_train.csv'); P=pd.read_csv('cdft_piezo_pool.csv')
def anon(f):
 c=Composition(f).reduced_composition
 return tuple(sorted(round(v,6) for v in c.values()))
SD=[Structure.from_str(x,fmt='poscar') for x in D.poscar]; SP=[Structure.from_str(x,fmt='poscar') for x in P.poscar]
sgd=[SpacegroupAnalyzer(s,.05).get_space_group_number() for s in SD]; sgp=[SpacegroupAnalyzer(s,.05).get_space_group_number() for s in SP]
matcher=StructureMatcher(ltol=.25,stol=.35,angle_tol=7,primitive_cell=True,scale=True,attempt_supercell=False)
for j,(r,s) in enumerate(zip(P.itertuples(),SP)):
 matches=[]
 for i,(q,t) in enumerate(zip(D.itertuples(),SD)):
  if anon(r.formula)!=anon(q.formula): continue
  try: result=matcher.get_rms_anonymous(s,t)
  except Exception: continue
  if result is not None and result[0] is not None: matches.append((float(result[0]),q.formula,q.d_ij,sgd[i]))
 if matches:
  matches.sort(key=lambda z:z[0])
  print(r.candidate_id,r.formula,'sg',sgp[j],':','; '.join(f'{f} d={d:.2f} sg={sg} rms={x:.3f}' for x,f,d,sg in matches[:6]))
